#!/usr/bin/env bash
# Shared plumbing for prepare.sh and teardown.sh: resolves the worktree's
# identity from the VINTA_WORKTREE_* environment (or from a name given on the
# command line), and provides the small helpers both scripts use. Sourced, never
# run. Generated by the vinta-ai-workflows bootstrap; owned by this project now.
#
# Bash 3.2 compatible (the macOS system bash): no associative arrays, no
# ${var,,}, no mapfile.

DRY_RUN="${VINTA_WORKTREE_DRY_RUN:-0}"
FORCE="${VINTA_WORKTREE_FORCE:-0}"
name_arg=""
for arg in "$@"; do
  case "$arg" in
    --dry-run) DRY_RUN=1 ;;
    --force) FORCE=1 ;;
    -h|--help) sed -n '2,/^set -euo/p' "$0" | sed '$d'; exit 0 ;;
    -*) echo "unknown option: $arg" >&2; exit 2 ;;
    *) name_arg="$arg" ;;
  esac
done

# Resolves symlinks in the deepest part of a path that exists. `git worktree
# list` prints resolved paths, so every comparison against it needs this (on
# macOS /var and /tmp are symlinks into /private).
canon_path() {
  local p="$1" rest=""
  while [ ! -d "$p" ]; do rest="/$(basename "$p")$rest"; p="$(dirname "$p")"; done
  printf '%s%s' "$(cd "$p" && pwd -P)" "$rest"
}

MAIN="$(canon_path "${VINTA_MAIN_CHECKOUT:-$(git rev-parse --show-toplevel)}")"
NAME="${VINTA_WORKTREE_NAME:-$name_arg}"
if [ -z "$NAME" ]; then
  echo "usage: $0 <worktree-name> [--dry-run]  (or set VINTA_WORKTREE_NAME)" >&2
  exit 2
fi
case "$NAME" in
  *[!A-Za-z0-9._-]*) echo "worktree name may only use [A-Za-z0-9._-]: $NAME" >&2; exit 2 ;;
esac

# Project defaults, baked in at generation time. implement-plan always passes
# the VINTA_WORKTREE_* values explicitly; these only serve a human running the
# script by hand.
WORKTREE_ROOT="{{WORKTREE_ROOT}}"
DEFAULT_BASE_REF="origin/{{DEFAULT_BRANCH}}"
SUMMARY_DIR="{{SUMMARY_DIR}}"

case "$WORKTREE_ROOT" in /*) root="$WORKTREE_ROOT" ;; *) root="$MAIN/$WORKTREE_ROOT" ;; esac
# A root ending in "-" is the `../<repo>-wt-` sibling convention: no slash.
case "$root" in *-) default_path="$root$NAME" ;; *) default_path="$root/$NAME" ;; esac

WT_PATH="$(canon_path "${VINTA_WORKTREE_PATH:-$default_path}")"
BRANCH="${VINTA_WORKTREE_BRANCH:-$NAME}"
BASE_REF="${VINTA_WORKTREE_BASE_REF:-$DEFAULT_BASE_REF}"
KIND="${VINTA_WORKTREE_KIND:-single}"
PLAN_PATH="${VINTA_PLAN_PATH:-}"
SUMMARY="${VINTA_WORKTREE_SUMMARY:-$MAIN/$SUMMARY_DIR/$NAME.yaml}"

# Names derived from the worktree name. Every forked database, compose project,
# volume and cache key comes from these, so prepare.sh and teardown.sh always
# agree on what belongs to this worktree.
REPO_SLUG="$(basename "$MAIN" | tr -c 'A-Za-z0-9_\n' '_' | tr 'A-Z' 'a-z')"
WT_SLUG="$(printf '%s' "$NAME" | tr -c 'A-Za-z0-9_' '_' | tr 'A-Z' 'a-z')"
COMPOSE_PROJECT="${REPO_SLUG}_wt_${WT_SLUG}"
COMPOSE_OVERRIDE="$(dirname "$SUMMARY")/$NAME.docker-compose.override.yml"

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"

log() { printf '[%s %s] %s\n' "$(basename "$0" .sh)" "$NAME" "$*" >&2; }

# Runs a command, or prints it under --dry-run. For pipes or redirections, wrap
# them: run sh -c '...'.
run() {
  if [ "$DRY_RUN" = 1 ]; then
    printf '+ %s\n' "$*" >&2
  else
    "$@"
  fi
}

# The forked name for one of main's databases, e.g. app_dev -> app_dev_wt_lane_1.
forked_db_name() { printf '%s_wt_%s' "$1" "$WT_SLUG"; }

# Hosts a database URL may point at for this script to fork or drop it. Add the
# project's compose service names (e.g. "db") when the DB runs in compose.
LOCAL_DB_HOSTS="localhost 127.0.0.1 ::1"

# Refuses anything but a local database. Forking or dropping is only ever done
# against a developer's own server, never a shared or remote one. Never prints
# the URL: it can carry a password.
require_local_url() {
  local rest host allowed
  case "$1" in sqlite:*|file:*) return 0 ;; esac
  rest="${1#*://}"
  rest="${rest##*@}"
  case "$rest" in
    \[*) host="${rest#\[}"; host="${host%%\]*}" ;;
    *) host="${rest%%[:/?]*}" ;;
  esac
  for allowed in $LOCAL_DB_HOSTS; do
    [ "$host" = "$allowed" ] && return 0
  done
  echo "refusing to fork or drop a database on non-local host '$host' (allowed: $LOCAL_DB_HOSTS)" >&2
  exit 1
}

# Refuses to drop a database this worktree did not create.
require_forked_name() {
  case "$1" in
    *_wt_"$WT_SLUG") return 0 ;;
  esac
  echo "refusing to drop '$1': it is not a '*_wt_$WT_SLUG' database" >&2
  exit 1
}

# Copy-on-write clone of a directory from main into the worktree: APFS clonefile
# on macOS, reflink on btrfs / XFS, plain copy elsewhere. Links inside the tree
# stay links, which keeps pnpm's relative-link store valid.
clone_dir() {
  [ -e "$MAIN/$1" ] || { log "skip $1 (absent in main)"; return 0; }
  run mkdir -p "$(dirname "$WT_PATH/$1")"
  if [ "$(uname)" = Darwin ]; then
    run cp -ac "$MAIN/$1" "$WT_PATH/$1"
  else
    run cp -a --reflink=auto "$MAIN/$1" "$WT_PATH/$1"
  fi
}

copy_file() {
  [ -e "$MAIN/$1" ] || { log "skip $1 (absent in main)"; return 0; }
  run mkdir -p "$(dirname "$WT_PATH/$1")"
  run cp -p "$MAIN/$1" "$WT_PATH/$1"
}

# Sets KEY=VALUE in a worktree env file, replacing an existing line for KEY.
set_env() {
  local file="$WT_PATH/$1" key="$2" value="$3"
  if [ "$DRY_RUN" = 1 ]; then printf '+ set %s in %s\n' "$key" "$1" >&2; return 0; fi
  touch "$file"
  grep -v "^$key=" "$file" > "$file.tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$file.tmp"
  mv "$file.tmp" "$file"
}

# YAML scalar: null for empty, single-quoted otherwise.
yaml_str() {
  if [ -z "$1" ] || [ "$1" = null ]; then
    printf 'null'
  else
    printf "'%s'" "$(printf '%s' "$1" | sed "s/'/''/g")"
  fi
}

# YAML flow list from space-separated words.
yaml_list() {
  local out="" sep="" item
  for item in $1; do out="$out$sep$(yaml_str "$item")"; sep=", "; done
  printf '[%s]' "$out"
}
